package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class Monocle2DifferentialTest {
    @TempDir Path temp;
    private static Map<String,Object> formula(String... names){return Map.of("intercept",true,"terms",Arrays.stream(names).map(n->Map.of("column",n)).toList());}
    private Map<String,Object> analysis(){var m=new LinkedHashMap<String,Object>();m.put("id","test");m.put("seed",1);m.put("family","negbinomial.size");m.put("lower_detection_limit",0.1);m.put("estimate_size_factors",true);m.put("dispersion",Map.of("estimate",false));m.put("relative_expr",true);m.put("full_model",formula("age","batch"));m.put("reduced_model",formula("batch"));return m;}
    private Map<String,Object> raw(){var m=new LinkedHashMap<String,Object>();m.put("schema_version",1);m.put("mode","DIFF");m.put("version","2.26.0");m.put("matrix_format","dense-tsv");m.put("expression_units","raw-integer-counts");m.put("expression","expression");m.put("cell_metadata","cell-metadata.tsv");m.put("gene_metadata","gene-metadata.tsv");m.put("metadata_types",Map.of("age",Map.of("type","numeric"),"batch",Map.of("type","factor","levels",List.of("NA","β"))));m.put("out","result");m.put("rscript","missing-Rscript");m.put("r_home","missing-R-home");m.put("r_libraries",List.of("missing-library"));m.put("analyses",List.of(analysis()));return m;}
    private void inputs()throws IOException {Files.writeString(temp.resolve("expression"),"gene_id\t cell\"β \tNA\ngene β\t1\t2\nNA\t3\t4\n");Files.writeString(temp.resolve("cell-metadata.tsv"),"cell_id\tage\tbatch\n cell\"β \t1.5\tNA\nNA\t2e0\tβ\n");Files.writeString(temp.resolve("gene-metadata.tsv"),"gene_id\tgene_short_name\ngene β\t symbol\" β \nNA\tNA\n");}
    private Monocle2DifferentialInputs.Population population(Map<String,Object> m)throws IOException{return Monocle2DifferentialInputs.validate(temp,Monocle2DifferentialRequest.parse(m,temp));}
    @Test void literalAxesRemainExact()throws Exception {inputs();var p=population(raw());assertEquals(List.of(" cell\"β ","NA"),p.cells());assertEquals(List.of("gene β","NA"),p.genes());assertEquals(4,p.storedEntries());}
    @Test void sparseCoordinatesAreOrderedByMetadataWithoutSummation()throws Exception {inputs();var m=raw();m.put("matrix_format","matrix-market");Files.writeString(temp.resolve("expression"),"%%MatrixMarket matrix coordinate real general\n% control\n2 2 3\n2 2 4\n1 1 1\n1 2 0\n");var p=population(m);assertEquals(3,p.storedEntries());assertEquals(1,p.explicitZeros());Files.writeString(temp.resolve("expression"),"%%MatrixMarket matrix coordinate real general\n2 2 2\n1 1 1\n1 1 2\n");assertThrows(IOException.class,()->population(m));}
    @Test void integerBannerRejectsFractionalContinuousEntries()throws Exception {inputs();var m=raw();m.put("matrix_format","matrix-market");m.put("expression_units","continuous");var a=analysis();a.put("family","uninormal");a.put("estimate_size_factors",false);a.put("relative_expr",false);m.put("analyses",List.of(a));Files.writeString(temp.resolve("expression"),"%%MatrixMarket matrix coordinate integer general\n2 2 1\n1 1 1.25\n");assertThrows(IOException.class,()->population(m));}
    @Test void denseOrderAndPopulationAreNeverRepaired()throws Exception {inputs();Files.writeString(temp.resolve("expression"),"gene_id\tNA\t cell\"β \ngene β\t1\t2\nNA\t3\t4\n");assertThrows(IOException.class,()->population(raw()));inputs();Files.writeString(temp.resolve("gene-metadata.tsv"),"gene_id\tgene_short_name\nNA\tNA\ngene β\tg\n");assertThrows(IOException.class,()->population(raw()));}
    @Test void responseUnitsAndExactIntegerDomainAreChecked()throws Exception {for(String bad:List.of("NA","NaN","Inf","-1","0.5","9007199254740992","1e999"))assertThrows(IOException.class,()->Monocle2DifferentialInputs.numeric(bad,"raw-integer-counts"),bad);assertEquals(1000,Monocle2DifferentialInputs.numeric("1e3","raw-integer-counts"));assertEquals(0.4,Monocle2DifferentialInputs.numeric("0.4","proportions"));assertThrows(IOException.class,()->Monocle2DifferentialInputs.numeric("0.4","binary"));assertThrows(IOException.class,()->Monocle2DifferentialInputs.numeric("1.1","proportions"));}
    @Test void explicitFamilyUnitsAndOptionsCannotBeInferred()throws Exception {for(String family:List.of("negbinomial.size","negbinomial","uninormal","binomialff")){var m=raw();var a=analysis();a.put("family",family);a.put("relative_expr",false);a.put("estimate_size_factors",false);m.put("expression_units",family.equals("uninormal")?"continuous":family.equals("binomialff")?"binary":"raw-integer-counts");m.put("analyses",List.of(a));assertEquals(family,Monocle2DifferentialRequest.parse(m,temp).analyses().get(0).get("family"));}var m=raw();m.put("expression_units","TPM");assertThrows(IOException.class,()->Monocle2DifferentialRequest.parse(m,temp));var a=analysis();a.put("family","binomialff");var invalid=raw();invalid.put("analyses",List.of(a));assertThrows(IOException.class,()->Monocle2DifferentialRequest.parse(invalid,temp));}
    @Test void reducedTermsMustBeStrictlyNestedAndIdentical()throws Exception {for(Map<String,Object> reduced:List.of(formula("age","batch"),formula("unknown"),Map.<String,Object>of("intercept",true,"terms",List.of(Map.of("column","age","spline_df",3))))){var m=raw();var a=analysis();a.put("reduced_model",reduced);m.put("analyses",List.of(a));assertThrows(IOException.class,()->Monocle2DifferentialRequest.parse(m,temp));}}
    @Test void arbitraryCodeUnknownKeysAndReservedNamesAreRefused()throws Exception {for(String key:List.of("script","input_rds","formula")){var m=raw();m.put(key,"system('x')");assertThrows(IOException.class,()->Monocle2DifferentialRequest.parse(m,temp));}for(String c:List.of("Size_Factor","NA_real_","system('x')")){var m=raw();m.put("metadata_types",Map.of(c,Map.of("type","numeric")));assertThrows(IOException.class,()->Monocle2DifferentialRequest.parse(m,temp));}}
    @Test void zeroSizeFactorCellsAndInputCapacitiesRefuseAnalysis()throws Exception {inputs();Files.writeString(temp.resolve("expression"),"gene_id\t cell\"β \tNA\ngene β\t0\t2\nNA\t0\t4\n");assertThrows(IOException.class,()->population(raw()));inputs();var m=raw();m.put("maximum_dense_entries",3);assertThrows(IOException.class,()->population(m));}
    @Test void missingRuntimeSkipsWithProminentRecoveryAndNoResult()throws Exception {inputs();NextflowFiles.writeJson(temp.resolve("request.json"),raw());var output=new ByteArrayOutputStream();var error=new ByteArrayOutputStream();assertEquals(3,Monocle2DifferentialCli.run(new String[]{"--request",temp.resolve("request.json").toString()},new PrintStream(output,true,StandardCharsets.UTF_8),new PrintStream(error,true,StandardCharsets.UTF_8)));var state=Monocle2DifferentialCli.read(temp.resolve("result/analysis-status.json"),1048576);assertEquals(false,state.get("result_admitted"));assertEquals("SKIP3_DEPENDENT_ANALYSIS_SKIPPED",state.get("status"));assertFalse(Files.exists(temp.resolve("result/results")));assertTrue(Files.readString(temp.resolve("result/WARNINGS.md")).contains("REQUIRED ACTION:"));assertTrue(error.toString(StandardCharsets.UTF_8).contains("SKIP3"));}
}
